WFJ.Data.add("quest", {
  [94003] = { "Skybreaker Bulwark", "Shrine of AkirのZaal StormshieldからSkybreaker Bulwarkを取り戻してください。", "私は、ここZephras IsleのSkybreakerの血筋の最後の一人だ。残りはAl'Akethに殺された。\n\n私の悲しみを上回るのは、恥だけだ。我が一族に伝わる盾――Skybreaker Bulwark――は今、Zaal Stormshieldという教団員の手にある。一族の言い伝えでは、この盾にふさわしい使い手には何の害も及ばないという。\n\nZaalがふさわしくないことは、確かだ。Shrine of Akirでこの男を見つけ、私の盾を取り戻してくれ。そうすれば、Skybreaker Defenseを教えよう。", nil, nil, 0xeef30912, 0x2a671f64, 0x9c8826cf, nil, nil, "...mm" },
  [94004] = { "Craftsman's Writ: Elixir of Ogre's Strength", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたそのメモには、Elixir of Ogre's Strengthを$N1個求める旨と、配達場所や支払いについての情報が記されている。下部には、この依頼書が譲渡可能であることを示す文言がある。>", nil, nil, 0x96235fbe, 0x89b8e7e5, 0xceb296e5, nil, nil, "...mm" },
  [94006] = { "Urseraの大いなる霊", "Valanaarの北東の滝の近くにいるUrs'endrisと話してください。", "ごきげんよう、{name}。あなたのドルイドとしての修行も十分に進みました。ここZephrasに住む偉大な精霊の一人に会う時が来たと思います。Urs'endrisは賢く気高い精霊で、何世代にもわたってドルイドにurseraの姿をとる方法を教えてきました。残念ながら、彼の領域もZephrasの他の多くの場所と同じように、枯れて空へと崩れ落ち始めています。\n\n彼を見つけるには、Shrine of Akirの陰にある滝の近く、北東へ向かってください。彼がさらに導いてくれるはずです。", nil, nil, 0xd845fe86, 0x00a57812, 0x6204789e, nil, nil, "...mm" },
  [94007] = { "獣を手なずける", "ValanaarのQuel'ana Quickgaleに報告してください。", "高地の荒野にもある程度慣れてきたようだから、そろそろ自分だけの動物の相棒を探す時だと思う。\n\n南東のValanaarの港へ行き、そこにいるQuel'ana Quickgaleと話してくれ。彼が獣を手なずける技を教えてくれるだろう。", nil, nil, 0xecd97a9a, 0x87db1216, 0xab76e227, nil, nil, "...mm" },
  [94013] = { "獣を手なずける", "Taming Rodを使ってGustberry LowlandsのVuldren Alphaを手なずけてください。技を練習したら、Taming RodをValanaarのQuel'ana Quickgaleに返してください。", "2頭の獣を手なずけて、見事に戻ってきたな。いよいよ最後の試練の時だ。Zephrasの風が、この先にさらなる難題が待つとささやいている。\n\nこのTaming Rodを持ってGustberry Lowlandsへ向かえ。そこでVuldren Alphaを手なずけ、お前の腕前を証明するのだ。\n\nこの教えをやり遂げれば、ハンターのより深い道を学ぶ準備が整うだろう。", "君は学ぶだろう、{name}。そしていつの日か、偉大な{class}になるだろう。", "見事だ、{name}！君は実に覚えが早い。基本を身につけた今、動物の相棒と長く続く絆を結ぶ方法を教えられる。\n\nこの知識を携えて行き、栄えよ。Zephras Isleが必要とする{class}であれ。", 0xecd97a9a, 0xd6749188, 0x420fabee, 0xe5057f89, 0x5c64ed8c, "....." },
  [94050] = { "獣を訓練する", "ValanaarのQuel'dora Quickgaleと話してください。", "これでペットを手なずける力を得たが、それを訓練する技も身につけねばならない。それには私の姉妹、Quel'doraに勝る者はいない。彼女が新しいペットを訓練する力を授けてくれるだろう。\n\n風と共に行け、若き{class}よ。", nil, "駆け出しの{class}だな。よかろう、ペットを訓練し導くのに必要な技を授けよう。ペットに新しい能力を教えられるだけでなく、これからはペットに餌を与え、戦いで倒れたときには蘇らせることもできるようになる。\n\n忘れるな、{name}。常に均衡を重んじ、周りの自然に畏敬の念を抱いて生きるのだ。さあ、行くがよい。また後日、話そう。", 0xdbeedc0e, 0xa8d2fa5d, 0x1f82d9d8, nil, 0xfbd746d0, "...m." },
