  [94357] = { "Craftsman's Writ: Cenarion Herb Bag", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Cenarion Herb Bagを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0x69c4d25e, 0x89b8e7e5, 0x3af81970, nil, nil, "...mm" },
  [94358] = { "Craftsman's Writ: Shadoweave Mask", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Shadoweave Maskを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0x98796734, 0x89b8e7e5, 0xcc7dfbdd, nil, nil, "...mm" },
  [94359] = { "Craftsman's Writ: Ghostweave Vest", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Ghostweave Vestを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0x8cf903cf, 0x89b8e7e5, 0x8ace6ad3, nil, nil, "...mm" },
  [94360] = { "Craftsman's Writ: Soul Pouch", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Soul Pouchを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0xbdabef1c, 0x89b8e7e5, 0x0b60ca87, nil, nil, "...mm" },
  [94369] = { "Zephrasの運命", "ValanaarのTalaanis Shadowsongと話してください。", "Ansiremからエレメンタルの王たちについて多くを聞いたが、Zephrasを隠していた守りが消えた今、Al'Akirを恐れる十分な理由があるのではないかと心配している。もしWindlordが我々を攻めると決めたら、彼の領域にいるここでは、身を守る術はまったくない。\n\nHigh Elder Shadowsongは我々が置かれている危険を知る必要がある。そして何より、Azerothへの任務で我々が何を目指しているのかをだ。我々は故郷を救う手立てを見つけ出す。誓おう。", nil, "<Shrine of Akirの上で起きたこと、そしてZephras Isleを去るというElaadrinの計画を話すと、Talaanis Shadowsongはじっと耳を傾ける。>\n\nさらに考えねばならぬが、良い面を見れば、我らはLorthunaを退け、教団から指導者を奪った。我らの故郷はまだ侵されてはおらぬ。元素の半神たちの時の流れからすれば、Al'Akirが我らに目を向けるまでには何年も……いや、何十年もかかるやもしれぬ。\n\n今は恐れるべきことも多いが、祝うべきことも多いのだ。", 0x6d3ea2fe, 0x4440ff8a, 0xbee20486, nil, 0xb4e92149, "...m." },
  [94373] = { "大地の呼び声", "Frostmane Bear Pendantsを2つ、AnvilmarのTeo Hammerstormに届けてください。", "うむ、時は来た、若きシャーマンよ。お前さんは足元の石のように、たくましく頑丈に育った。シャーマンの道を選んだってことは、まだ己を証明する前から山の知恵を備えとるってことだ。お前さんには大地の道を歩むだけの石の根性がある。\n\nだが、大地の加護を得るには、きちんと向き合わにゃならん。ここから南へ行くと、Frostmaneのトロールどもが洞窟に住んどる。\n\n奴らが身に着けとる、Iceclawの熊から作った首飾りを2つ持ってこい。そしたらお前さんの将来についてもっと話そう。", "若いの、忍耐こそ大地の最上の美徳だ。大地は山々が崩れ、川が谷を刻むのを見てきた。ゆっくりと頑固に、まことの{race}のようにな。今、大地がおぬしを呼んでおる。地平の彼方で厄介事が起きつつあるからだ。成し遂げて戻れば、おぬしは完全な姿へ一歩近づくだろう。\n\n他の者はおぬしの知恵を妬むかもしれんが、それはそいつらが背負う重荷よ。", "よくやったな、若いの。準備ができてると自分で証明してみせたな。大地は万物の岩盤だ。力、粘り強さ、忍耐。大地はおまえを守ってくれる。ただし、ちゃんと敬意を払えばの話だ。石だって、ないがしろにされりゃ動くもんさ。大地のやり方を学べば、たいていの者より賢くなれる。大地が分けてくれる秘密を決して忘れるなよ。\n\n今からおまえにsaptaを作ってやろう。受け取れば、真の道を歩むことになる。", 0xe316c17f, 0xc897beee, 0x70173b78, 0xd804d26a, 0xb1f39df1, "....." },
  [94374] = { "大地の呼び声", "Spirit Stoneを見つけ、Earth Saptaを飲んでください。", "うむ、saptaってのは魔法で作られた薬でな、わしらの魂を精霊と結びつけるものだ。そのレシピを知っとるシャーマンはほんの一握りで、意志の弱い者には向かん。飲めば、他の者には見えんものが見える。肝に銘じておけ。神聖な場所でしか飲んではならん。\n\n北のSpirit Stoneへ向かえ。山を登る隠れた道の突き当たりにひっそりとある。そこで飲むのだ……大地がお前さんに見せるものを見てこい。", nil, "ああ……{name}……この凍てついた地にあっても、大地はあなたを迎え入れます。体も魂も結ばれたあなたは、山々があなたの力であり、平原があなたの忍耐であり、世界があなたの本質であることを知りながら、前へと歩んでいくでしょう。\n\nこの儀式を乗り越えるには、大地の前に謙虚に立ちなさい。他の元素はそれほど静かではありません。ぶつかり合い、うなりを上げます。ここ、雪と石の中にあっても、それらの二面性を学びなさい。", 0xe316c17f, 0x4c31146f, 0x28284db1, nil, 0xcd853d2f, "...m." },
  [94375] = { "大地の呼び声", "Rough QuartzをAnvilmarのTeo Hammerstormに届けてください。", "このrough quartzを持って行き、わしと会った証としてTeo Hammerstormに渡すのだ。奴がお前さんのためにトーテムを作ってくれる。この小石がその心臓となる。小さく見えるかもしれんが、大きさなど問題ではないこと、どんなに小さなものでも多くのものより長く残りうることを、お前さんもいずれ知るだろう。\n\n辛抱するのだ、{name}。強くあれ。そして知恵を求めよ。それが大地がお前さんに求めるものだ。最後には、お前さんは大地とひとつになる。大地を敬え。大地もお前さんを敬うだろう。", "ああ、戻ったか。石を持っておるなら、山がおぬしをまことに選んだということだ。約束のトーテムを授けよう。だが手ぶらで来たのなら、去れ！この道は己の行くべき道を忘れる者のためのものではない。", nil, 0xe316c17f, 0x1c898e3e, 0x1415c33d, 0xa9c8dad9, nil, "....m" },
  [94411] = { "お節介なメイジたち", "Shen'dar HighlandsでHigh Order Apprenticesを6体倒してください。", "用心しなさい。村の北にある立石のあたりで、High Orderの者たちが目撃されています。我々の聖地に手を出すなと何度も警告してきたのに、彼らはますます大胆に我々を押しのけようとしています。立石へ行って彼らを追い散らし、あなたの決意を我々に示してください。\n\nあからさまな流血を認めるのは気が進みませんが、追い払うためにすべきことをしてください。終わったら私のところへ戻ってきなさい。", nil, "shen'doreiの兄弟姉妹と直接争えば、民としての私たちを弱めるだけです。ですが、より大きな悲劇を防ぐために、時には断固たる行動を取らねばなりません。\n\nHigh Orderのメイジたちは、自分たちの魔法による干渉がもたらす結果をまったく顧みません。私たちの島をつなぎとめている力はもろく、無防備です。たった一度の軽率な行動で、故郷が滅びてしまうかもしれないのです。", 0xf63c825c, 0xff42e97b, 0x0bc960b1, nil, 0x717d680d, "...m." },
  [94413] = { "魔法による侮辱", "Shen'dar HighlandsでWindshaper Novice Seersを6体倒してください。", "最近Zephrasの地表にレイラインが現れたことは、我らの結社にとって大きな意味を持っている。この地に満ちるエネルギーに、より直接的で確かな形で触れられるようになり、その魔法への理解は大いに深まった。\n\nしかしWindshapersは、これらの出現を「癒やす」べき大地の傷跡とみなしている。これは我らの結社への侮辱であり、とうてい容認できるものではない。\n\n南西の森にあるレイラインへ行き、そこにいるWindshapersを追い払ってくれ。", nil, "時々、Al'Aketh教団の盲目的な狂信と、変わることを頑なに拒むWindshapersとの区別がつかなくなります。\n\n風が私たちを導くと本当に信じているのなら、風が吹いている方向を感じ取り、風に逆らうのではなく、共に流れるべきです。", 0x28568d0e, 0x3affac9b, 0x795cdf90, nil, 0x545f7f62, "...m." },
  [94414] = { "Zephrasの錨", "Halaan Hawk-Eyeと話し、彼の力を借りて遠くの錨の塔を見てください。", "ごきげんよう、若き{name}よ。私はよくここへ来て、古きアンカーパイロンを眺めているのです。風の精霊たちからの贈り物であるそれらは、我らの島を結びつけ、支えています。けれど近頃、その魔法は不安定で、むらのあるものになってしまいました。\n\n私に見える限り、パイロンたちに苦しんでいる様子はありません。その輝きも変わっていません。\n\nよければ、あなた自身の目で見られるよう、私の授かった力を貸してあげましょう。", "私の才は単純で、ありふれたものです。空を見通す目を持つ者のように世界の狭間を覗き見ることも、他の者たちのようにZephrasの地下を走るレイラインの魔法を引き出すこともできません。それでも才であることに変わりはなく、それを持てることに感謝しています。\n\n自分の持っているものをありがたく思うことが、幸せへの鍵です。手に入るかもしれないもの、あるいは失ったものを切望しても、絶望につながるだけです。", "わざわざ時間を割いて話してくれてありがとう。私はこれからも木立を見守り、故郷の状況について思いを巡らせるつもりです。", 0x238731a9, 0x1acadf70, 0x825195ca, 0x87436f19, 0x8e28660b, "....." },
  [94427] = { "神性の教え", "UndercityのTanis Alderwoodと話してください。", "パラディンであることの重要な教えの一つは、神聖さの追求だ。これは神になることを追い求めるのではなく、ただ善そのものを、善のために追い求めることだ。我々は皆、何らかの悲劇を経てここにたどり着いた。だから、生前にパラディンとしての我々を形作っていたあの恩寵を失うのはたやすいだろう。\n\nUndercityへ行き、Trade QuarterにいるTanis Alderwoodを探せ。その者は困っていて、いくらかの恩寵があれば大いに救われるはずだ。", nil, "あ……あんたは{class}なのか？頼む、傷つけないでくれ。も、物乞いをしちゃいけないのは分かってる。あんたにも、あんたの騎士団にも何の恨みもない。放っておいてくれ、お願いだ！", 0x58def706, 0xf413a91f, 0x7c21c569, nil, 0xf3a1f005, "...m." },
  [94434] = { "神性の教え", "Linen Clothを10枚、UndercityのTanis Alderwoodに届けてください。", "待ってくれ、あんたが……助けたいって？なんでパラディンが俺みたいな物乞いを助けたがるんだ？\n\nまあ、少しは役に立ってもらえるかもしれないな。\n\n女房のことなんだ。あいつは、その……崩れかけてるんだ。文字どおりの意味でな。薬剤師たちならあいつをすっかり元どおりに縫い合わせられるんだが、みんなDark Ladyの仕事で手一杯で、手を貸せる者が一人もいない。新しい布を持ってきてもらえたら、薬剤師たちを待つ間、せめてあいつの体をつなぎとめておく包帯を作ってやれるんだが。", "ご迷惑でなければよいのですが、善き{class}よ。", "なんと親切な、{class}。本当に親切だ。", 0x58def706, 0xde430c6a, 0x44288d78, 0x802e37b7, 0x14051e15, "....." },
  [94435] = { "神性の教え", "Bandarion KeepのDanitha Morrのところへ戻ってください。", "なんでわざわざ俺を助けてくれるのかわからないが、ありがたく思ってる。誰かにここへ寄こされたんなら、そいつにも感謝してると伝えてくれ。Tanis Alderwoodはいつでもあんたの友だ、{class}。", nil, "よくやった、{name}。小さなことではあったが、このようなささやかな奉仕でも、光との絆を強める助けになるかもしれん。\n\nDark Ladyとその配下の多くは我々を信用していない。中には我々に対して陰謀を巡らす者さえいる。だが我々は、彼らの疑念と恐れに勇気と正義をもって応えるのだ。我々がForsakenの一員であり、大きかろうと小さかろうと自分の役目を果たし、同胞が再び栄えるよう力を尽くす覚悟があることを示してやろう。\n\nこの聖印を受け取れ。次に待つことのために必要になる。", 0x58def706, 0x4528f784, 0xb51d252f, nil, 0x44a723ff, "...m." },
  [94436] = { "神性の教え", "Bandarion KeepのDeathguard Billmuthと話してください。\n\nSymbol of Lifeをなくしてしまったら、Danitha Morrのところへ戻れば代わりをもらえます。", "光の最も偉大な賜物のひとつを導く力を示す時だ。\n\n今渡した品はSymbol of Lifeという。気をつけろ。このような光の護符を扱うのは、少々苦痛を伴うかもしれない。光は我々を生み出した力にとっては忌むべきものかもしれないが、それでも我々の導き手であり味方だ。痛みがそれを思い出させてくれる。\n\n下の階のDeathguard Billmuthに会いに行け。彼は着いたばかりで、我々に助けを求めてきた。真のパラディンに何ができるか、彼とForsakenに見せてやれ。", nil, "じゃあ、助けてくれるのか？よし、よし。正直、こんな手段に……その、パラディンに助けを求めるなんて手段に頼るのは誇れることじゃない。プリーストたちには追い払われたし、あんたが友の唯一の望みかもしれないんだ。\n\n頼む、助けてくれ。", 0x58def706, 0x5c7b44af, 0xb27ae887, nil, 0x717a9a7b, "...m." },
  [94438] = { "神性の教え", "Symbol of Lifeを持っていき、それを使ってVenomweb ValeでDeathguard Falganを蘇生させてください。\n\nSymbol of Lifeをなくしてしまったら、Danitha Morrのところへ戻れば代わりをもらえます。", "Falganと俺は、Venomweb Valeでのscarletの動きを偵察する任務に就いていた。奴らの野営地のひとつに十分近づいて、Brillへの攻撃に関する新しい命令を聞き出すことができた。だが次にどうするか決める前に、俺が小枝を踏んで、その音で奴らに気づかれちまった。\n\nFalganが俺に逃げろと叫んだから、俺は逃げた。奴がついてきていないと気づいた時には、もうBrillまで半分のところだった。あの勇敢な馬鹿は、俺のために奴らを食い止めようと残ったんだろう。\n\n頼む、俺の友を見つけて、できるなら助けてやってくれ。", nil, "私は……戻ってきたのか？しかも{class}に救われるとは？Symbol of Lifeを持っているのだな。そんな物は……そう、Lordaeronがまるで違う場所だった戦争の前から見ていない。君は助けに来てくれたのだろう。私とBillmuthは、この辺りのscarletの動きを偵察するためにここへ送られ、奴らが何らかの攻撃を計画していることを突き止めた。\n\nさらに力を貸してくれるなら、Forsakenのために君にできることはまだあるかもしれない。", 0x58def706, 0xc86dfaf3, 0x7442e1a0, nil, 0x4251ced7, "...m." },
  [94440] = { "神性の教え", "Venomweb ValeのScarlet CrusadersからScarlet Crusade Attack Plansを奪い、Tyr's WatchのDeathguard Billmuthのところへ戻ってください。", "このScarlet Crusadersどもは、配置命令の入った鞄をよく持ち歩いている。攻撃が来るのはわかっているが、奴らの命令を取り戻せれば、残りのDeathguardに警告して待ち伏せの準備ができる。\n\nお前は明らかに見事なパラディンだ。scarletの獣どもを殺し、奴らの命令書の写しを取り戻して、Deathguard Billmuthのもとへ持っていけ。あとは彼がやってくれる。", "Deathguard Falganの知らせは何かあるか？", "友を救ってくれてありがとう、{name}。この計画書を司令官のもとへ持ち帰り、あの十字軍どもに忘れられない歓迎をしてやる。\n\n我々の同胞の多くがお前たちパラディンを信用していないのは知っている。だが、お前が骨の髄までForsakenなのは明らかだ。このことは忘れない。今日お前がここでしたことを、他の者たちにも必ず伝えよう。", 0x58def706, 0x76a3e5d1, 0x03204cbb, 0x310d83d6, 0xf2ce722f, "....." },
  [94441] = { "神性の教え", "Bandarion Keepの砦にいるDanitha Morrと話す。", "Danitha Morrに私の感謝を伝えてくれ。そしてTyr's Watchのパラディンたちが我々のために果たした務めのことは、Deathguardの皆にも知れ渡るだろうと伝えてほしい。\n\nお前はパラディンとして大いに見込みがある。お前のような者がForsakenの一員であることを誇りに思う。Dark Ladyがお前を見守らんことを、{name}。", nil, "Symbol of Lifeは、光の最も偉大な祝福のひとつを用いる準備ができた{class}にしか使えない。君を我々の一員に数えられることを誇りに思う。今こそ君に救済の力を授けよう。これで倒れた仲間を蘇らせることができる。この新たな恵みを賢く使うのだ。\n\n君はForsakenのためにも、Tyr's Watchのパラディンたちのためにもよく尽くしてくれた。同じForsakenの心をつかむために踏み出せる一歩は、どれも努力する価値が十分にある。光と共に行け、{name}。", 0x58def706, 0x5ae2079a, 0x9f0c78b8, nil, 0x9201f4b7, "...m." },
  [94449] = { "火の呼び声", "Dun MoroghでBruegs Kindlebornを見つけてください。", "お前さんが最後に試されてから、ずいぶん経ったな、{name}。お前さんは忍耐を示した。うむ……だが今こそ、混沌を……破壊を学ぶ時だ。火の呼び声は大きい。その代償を払う覚悟があるなら、火はお前さんに語りかけるだろう。\n\nはるか東の山中にいるBruegs Kindlebornを訪ねよ。奴はSouth Gate Outpostの上の洞窟に住んでおる。お前さんが本当に準備できておるか、奴ならわかるはずだ。", nil, nil, 0x53f3b76b, 0x15200cd4, 0xf3c2198f, nil, nil, "...mm" },
  [94465] = { "火の呼び声", "Torch of the Dormant FlameをLoch ModanのBraldir Ashmantleに届けてください。", "うむ、お前さんには火のトーテムを担うだけの力がある、若いの。だが力だけでは準備ができたことにはならん。\n\nValley o' Kingsの向こう、Loch Modanの岩山に、わしらの聖なる峰のひとつへ通じる隠れた道がある。そこでBraldir AshmantleがShrine o' the Dormant Flameを守っておる。\n\nこの松明を奴のところへ持っていけ。お前さんの意志を示すものだ。祠の火鉢で火を灯して持ち帰れば、トーテムをきちんと授かれるよう取り計らおう。", nil, nil, 0x53f3b76b, 0xef8da8e8, 0x415200cc, nil, nil, "...mm" },
  [94466] = { "火の呼び声", "Fire Tarを1つとReagent Pouchを1つ、Loch ModanのBraldir Ashmantleに届けてください。", "ふん、昔話を聞くためにはるばる来たわけではなかろう、{name}？ お前さんが求めておるのはEternal Flameと火のトーテムだな。\n\nまずは、お前さんの魂を炎に結びつけるsaptaが要る。\n\nわしが作ってやろう。だがそれには2つのものが要る。北のコボルドの洞窟にいるTunnel Rat Geomancersのfire tarと、南の丘に潜むStonesplinter Seerのreagent pouchだ。危険な仕事だが、炎にふさわしい仕事だ。", nil, nil, 0x53f3b76b, 0x1ec23f46, 0x08842bb0, nil, nil, "...mm" },
  [94467] = { "火の呼び声", "Minor Manifestation of Fireを倒し、Shrine of Eternal Flameの頂上にある火鉢にGlowing Emberを置いてください。", "火のsaptaができたぞ、{name}。さあ、炎と向き合え。祠でそれを使い、それから頂上へ登るのだ。そこで精霊が見える。お前さんが仕掛けるまで向こうは打ってこんが、お前さんに見られていることには気づくだろう。\n\n素早く打て、若いの。待てば待つほど、奴は強く燃える。奴が倒れたら、そのglowing embersを取って火鉢に入れろ。松明に火を灯し、火の加護を勝ち取るのだ。", nil, nil, 0x53f3b76b, 0x7d09c623, 0xbfb4503b, nil, nil, "...mm" },
  [94468] = { "火の呼び声", "Torch of Eternal FlameをDun MoroghのBruegs Kindlebornに届けてください。", "松明をしっかりと手に握り、あなたは火鉢に背を向けてLoch Modanを見渡す。風が強まって炎を激しく踊らせると、魂が高揚に引っ張られるのを感じる。\n\nあなたはBruegs Kindlebornを探して、Dun Moroghへ戻る道を下り始める。", nil, nil, 0x53f3b76b, 0x8fb8c297, 0x74b18970, nil, nil, "...mm" },
  [94472] = { "Earth Sapta", "Teo Hammerstormと話して、Earth Saptaをもう一つもらってください。", nil, nil, "これを受け取り、覚えておけ。これは神聖なものだ。", 0x9c7e1740, 0x0b15db68, nil, nil, 0x794bb81e, "..mm." },
  [94473] = { "Fire Sapta", "もう一つのFire Saptaをもらうため、Braldir Ashmantleと話して下さい。", nil, nil, nil, 0xe8738c8b, 0x60e76b9e, nil, nil, nil, "..mmm" },
  [94484] = { "不気味な静寂", "Shadowgale Forestの北東部にいるElegael Thornpawを見つけて話してください。", "少しよろしいですか、{name}。Shadowgale Forestへ向かわれるのですか？その北東の洞窟に、ドルイドの集会があるのです。彼らからの知らせを待っているのですが、便りはとうに届いているはずの頃を過ぎています。\n\nBan'aethallが廃墟となり、近頃は騒乱も続いているので、何か恐ろしいことが起きたのではないかと心配なのです。どうか、もしできるなら、Elegael Thornpawを訪ねて、私を安心させてください。", nil, "我々の知らせがLotheluumに届いてよかった。待て、残りの援軍はどこだ？まさか、送られてきたのは君だけではあるまいな？\n\n<Lotheluumとの会話を伝えると、Elegaelは青ざめる。>\n\nでは、知らせは届かなかったのか。ならば我々は本当に窮地に立たされているな。\n\nどうやら自分たちだけで対処しなければならないようだ。一刻を争うぞ。", 0xa432cf89, 0xabfdd6fd, 0x39195fc1, nil, 0xe259eba5, "...m." },
  [94485] = { "奥方の涙", "Lady's Tear Mossを$N1個集めてください。", "Nightclaw Denにいる仲間たちを救うには、湿布の材料がいくつか必要です。最初の、そして最も大切なものは、Lady's Tearと呼ばれる細長い苔です。ここShadowgaleでは、たいてい木の根元に生えています。\n\nこの苔は消毒作用のある粘り気のある液を出し、開いた傷を閉じるのにうってつけなのです。手の届く範囲でわずかに集めましたが、この森にはもっとあるはずです。\n\nさあ、急いでください。残してきた負傷者たちがまだ生きているなら、たくさん必要になります。", "Lady's Tearは見つかったか？", "<Elegaelは弱々しく微笑みながら、あなたからべとべとした苔の塊を受け取る。>\n\nありがとう、{name}。よくやってくれた。まさにこれが必要だったんだ。", 0x58e6b1d0, 0xfef31217, 0xb28e5c04, 0xa4512f51, 0x12fdd838, "....." },
  [94486] = { "束ねるための羽根", "Shadowgale ForestのShadowgale Shrieklingから羽根を$N1枚集めてください。", "湿布に必要なもうひとつの材料は、この森をうろつくShadowgale shrieklingsの羽根です。幼いshrieklingsの羽根は断熱性があり、苔の上にかぶせるのに理想的なのです。この羽根が消毒作用のある樹液の乾燥を防ぎ、風雨からも少しは守ってくれるでしょう。\n\n気をつけてください。shrieklingsは普段はおとなしいのですが、近頃はひどく凶暴になっています。油断すれば、その大きな鉤爪で簡単に腹を裂かれてしまいます。", "幼いshrieklingsを殺すよう頼むのは心から悲しいのですが、凶暴さが増している以上、それが最善なのです。一度に対処できる非常事態には限りがありますから。", "これをありがとう。彼らの犠牲が無駄にならないよう、羽根はすべて余さず使うよ。", 0x311c98a1, 0x06470144, 0xcbaac9a6, 0x385872fb, 0x9943ca25, "....." },
  [94487] = { "望まれず、ふさわしからず", "Shadowgale ForestのAl'Aketh FootsoldierとAl'Aketh StormchaserからBloodied Heirloomを$N1個集めてください。", "Al'Aketh Cultistsは何の前触れもなく我々を襲った。奴らの動機はいまだに謎だ。この教団員どもの頭に雲が詰まっているのは知っていたが、これほど残忍なやり方でZephrasの繊細な均衡を乱すとは思いもしなかった。行け、できるだけ多く殺し、身に着けている家宝があれば奪ってこい。\n\n<Elegaelは唾を吐く。>\n\nこの嵐に呪われた教団員どもに、shen'doreiと呼ばれる資格はない。死体は森の獣どもにくれてやればいい。奴らの灰は風に乗せてやる価値もない。", "今日奴らが流したドルイドの血の一滴一滴に至るまで、教団に償わせてやる。", "<Elegaelは血に染まった家宝の数々を見下ろし、苦しげな表情を浮かべる。>\n\nあれほどの可能性を秘めた多くの若い命が、永遠に失われてしまった。これを返してくれてありがとう、{class}。\n\nHigh Elderのもとへ持っていけるまで、私が大切に預かっておこう。そこで再び収蔵品に戻され、次の、そしておそらくはより相応しい世代が成人するのを待つことになる。", 0x77a04507, 0xec40e0a6, 0x29badda2, 0xc4497c3b, 0x61cecea0, "....." },
  [94488] = { "結ぶ絆", "Commander Haalienを倒し、その首をShadowgale ForestのElegael Thornpawに届けてください。", "教団員どもがここにいる理由は今も分からんが、流血の向こうに覚えのある匂いがする。\n\n我らの環のドルイドの一人、Haalienが数か月前に姿を消した。どうやら奴は、その情けない身を教団員どもの側に投じたらしい。\n\n同胞の血を流せばどうなるか、奴に思い知らせてやれ！奴の首を取って、私のところへ持ってこい。", "我らの同胞の命は、お前にとって本当にそれほど軽いものなのか、Haalien？", "<Elegaelは切り落とされた首に顔をしかめるが、素っ気なくうなずく。>\n\nありがとう、{name}。どれほど怒りを抱えていても、自分のいとこを討つのは難しかっただろう。\n\n彼を悼むことはない。彼の無知と悪意が、今日多くの罪なき者を殺したのだ。", 0x0b0f4638, 0xa82e2486, 0x0a7343f3, 0xf01d0886, 0xd288d221, "....." },
  [94489] = { "裏切りの傷", "Nightfang Denに入り、ドルイドを$N1人治療して、Shadowgale ForestでJorel Windsingerを見つけてください。", "湿布ができました。急いで、洞窟にいるドルイドたちのところへ持っていってください。北へ、空き地をすぐ渡ったところです。仲間たちは私よりずっと危うい状態のはずです。きっと傷がひどくて自分で癒やすこともできないでしょう。私たちshen'doreiのドルイドはとても少ないので、ひとつひとつの命が貴重なのです。\n\n行く前に、身勝手なお願いがあります。私の伴侶のJorel Windsingerは、私が出てきた時にはひどい状態でした。どうか、まだ生きていたら、彼の傷を診てあげてください。", nil, "<Jorelの最期と、残りのドルイドたちの容態を伝えると、Elegaelの顔が青ざめる。>\n\nそんな……そんな！ これは私が思っていたよりずっと酷い――\n\n<Elegaelは嗚咽をこらえ、歯を食いしばって苦しげなうなり声をもらす。>\n\n報いを受けさせるわ。全員に報いを受けさせる。Al'akethと手を組む者は誰であろうと、私の怒りを思い知ることになる！ これは誓いよ。", 0xf524491f, 0x70ebec30, 0x3d5bdf31, nil, 0x6a75bca2, "...m." },
  [94490] = { "Ripped Missive", "Ripped MissiveをShadowgale ForestのElegael Thornpawに届けてください。", "<Haalienの腕当ての裏に、書き付けが挟まっている。戦いの中で少し破れ、血に汚れてしまったようだ。ドルイドの棲み処への襲撃について、教団員たちの動機に関する役立つ情報が書かれているらしい。Elegaelならこの情報に興味を持つだろう。>", nil, "彼らはパイロンが目当てでここに来たというの？ でも何のために？ 私たちは襲撃の本来の理由ではなかったということ？\n\n<Elegaelは怒りに震えながら読み進め、言葉が途切れる。>\n\n私たちが邪魔だったから、彼らは私の同胞を殺したのね！ カルト信者どもは一人残らずこの牙で引き裂いてやる！ 誰一人として生きてここから出させはしない。\n\n行って、急いで！ もし命令が本当にValanaarから出ていたのなら、そこに裏切り者が潜んでいる可能性が高いということ。この書簡をValannarのLotheluumに渡して、何が起きたのか伝えて。", 0xab8b8528, 0x38e9ba67, 0xc2dcf852, nil, 0xb05a5f41, "...m." },
  [94491] = { "巣穴の運命", "ValanaarのLotheluumに書簡を渡し、何が起きたのかを伝えて下さい。", "どうやらValanaarのどこかに内通者が潜んでいて、教団に情報を流しているようだ。私はとても旅のできる状態ではないが、ここで起きたことをLotheluumに知らせねばならない。\n\nもうこの世にいない者たちの運命も、彼に知らせるべきだ。お前の助けのおかげで、ここから先の事態は我々で対処できると思う。損害はもう出てしまったがな。\n\n急いでくれ、{name}。いつかまた我らの道が交わることを願っている。それまで、私には斬るべき教団員がいるのでな。", nil, "<ドルイドの巣穴での出来事を語ると、Lotheluumは心からの恐怖を顔に浮かべる。>\n\nす、すまない、{name}。少しだけ時間をくれ。この喪失を言い表す言葉が、私には見つからない。\n\nこれは実に重大な知らせだ。この書簡が偽造されたものでないなら、ここValanaarには、良くて共犯者、悪くすれば裏切り者がいることになる。すぐにこれをHigh Elderのもとへ持っていこう！ 同胞の犠牲を無駄にはさせない。", 0xef28fcc3, 0xbbf76165, 0x96f26dcc, nil, 0x880d65a8, "...m." },
  [94493] = { "無駄な犠牲", "Shadowgale Forestの北東部にいるElegael Thornpawと話してください。", "よかった、我々の知らせはLotheluumに届いたのだな。待て、残りの援軍はどこだ？まさか、送られてきたのはお前だけではあるまいな？\n\n<事情を説明すると、Elegaelは青ざめる。>\n\nでは、知らせはValanaarに届かなかったのか。ならば我々は本当に窮地に立たされている。\n\n<Elegaelは深くため息をつき、それから決然とした顔つきになる。>\n\nそれなら、我々だけで片をつけるしかない。一刻を争うぞ。", nil, nil, 0xaf28bd4e, 0xfc76d336, 0x11488683, nil, nil, "...mm" },
  [94494] = { "水の呼び声", "Loch ModanでNorric Lochthaneを見つけてください。", "お前さんが最後に試されてから長い時が経ったな、{name}。これまでの修行でお前さんは忍耐を示してきた。だが今こそ、水の清らかさについて学ぶ時が来た。\n\nLoch ModanにいるNorric Lochthaneを訪ねよ。湖の北西の岸沿い、Stonewrought Damの南におる。そこの穴蔵小屋で奴に会えるだろう。幸運を祈るぞ、{name}。", nil, nil, 0x1f0e11aa, 0xa614e79c, 0xf11bb23d, nil, nil, "...mm" },
  [94495] = { "水の呼び声", "WetlandsでHervdana Saegrundを見つけてください。", "水について学ぶべき真実がひとつあるとすれば、それはこれだ。水とは再生を意味する。水は石を削り、汚れを清め、疲れた者を癒やす。だが、それは清らかな時だけだ。汚されれば、触れるものすべてを台無しにする。\n\n水のsaptaを求めるなら、WetlandsのHervdana Saegrundを訪ねよ。あの娘の一家は南の滝の下の洞窟に住んでおる。\n\nさあ行け、川に追い越されるなよ。", nil, nil, 0x1f0e11aa, 0xadc7f213, 0xadd95e2e, nil, nil, "...mm" },
  [94497] = { "水の呼び声", "Hervdanaの洞窟の下にある滝の底でEmpty Brown Waterskinを満たし、Wetlandsにいる彼女のもとへ持ち帰ってください。", "あら、saptaを求めて来たってわけね？ それじゃよく聞いて、あんた。理解を得てsaptaを手に入れるには、さまざまな姿の水を探さなきゃならないの。見本を集めながら、目をしっかり開けておくこと。水を守る獣たち、水が潤す土地、そして水がどう命を変えるかをよく見るのよ。\n\nまずは簡単なところから。滝の根元の、真水と汽水が混じるところでこの水袋を満たしてきて。さあ行って、沼には気をつけてね。", nil, nil, 0x1f0e11aa, 0xa3d8f378, 0x4ed51e9b, nil, nil, "...mm" },
  [94499] = { "水の呼び声", "Nightcrawler Murlocsの近くにあるStonewatch FallsでEmpty Red Waterskinを満たし、WetlandsのHervdana Saegrundのところへ戻ってください。", "そうそう、RedridgeはLake Everstillからたっぷり水を飲んでるけど、その水がStonewatch Fallsを流れ落ちる頃には、何かが染み込んでるの。あそこのmurlocはでかくてねじれた乱暴者よ。ここやLochで見かけるのとは違うわ。町の人たちにとって幸いなことに、あいつらは滝の根元から出てこないけどね。\n\n水を少し汲んできて。あの古い砦の近くの水を汚してるのが魔法なのか、毒なのか、それとももっとひどい何かなのか、突き止めてやろうと思ってるの。", nil, nil, 0x1f0e11aa, 0x6ccca7b4, 0xa2cb5a4a, nil, nil, "...mm" },
  [94500] = { "水の呼び声", "AshenvaleのAstranaarの水でUnfilled Blue Waterskinを満たし、WetlandsのHervdana Saegrundのところへ戻ってください。", "この水袋を持って、Ashenvaleのエメラルド色の木陰の奥深くへ旅してこい。Astranaarは、穢れに染まっとらん水に抱かれるように佇んどる。湖の底には遺跡が散らばっとって、過ぎ去った時代をうかがわせる。湖から水を汲んできてくれ。清らかで、古く、ひょっとしたら魔力を帯びとるかもしれん水をな。\n\nそれが、お前さんをNorricのところへ送り返す前に、わしが必要とする最後の液体だ。\n\nMenethilから出るAuberdine行きの船に乗れ。途中でSouthshoreに寄るぞ。\n\nそれと、気をつけるんだぞ……森には目があって、そいつらは瞬きをせん。", nil, nil, 0x1f0e11aa, 0x76aef756, 0xc7e05766, nil, nil, "...mm" },
  [94501] = { "水の呼び声", "Vial of Purest WaterをLoch ModanのNorric Lochthaneに届けてください。", "水のトーテムの儀式で報いる前に、Norricはあんたにもうひとつ仕事を頼むはずよ。私が渡した水の小瓶は、その仕事が何であれ必要になるの。さあ行って、彼を見つけて。またいつか会いましょう。", nil, nil, 0x1f0e11aa, 0x0d508544, 0x58506c33, nil, nil, "...mm" },
  [94502] = { "水の呼び声", "WestfallのStendel's Pondの汚染を浄化してください。\n終わったらLoch ModanのNorricのところへ戻ってください。", "Westfallの、Moonbrookの外れにStendel's Pondがある。かつては清らかな泉だったが、今は闇の力に汚されておる。そこの精霊たちは黙り込んでしまった。\n\nお前さんはその水を汚す穢れと向き合わねばならん。そいつの腕輪と、Hervdanaの薬の最後の数滴を持って、祠に置け。そうすれば、清められた真の精霊が呼び出される。そいつと話し、学べることを学ぶのだ。\n\n事を成し遂げた証を持ってくれば、トーテムを授けよう。", nil, nil, 0x1f0e11aa, 0x5b8fcaa6, 0xcfb8681c, nil, nil, "...mm" },
  [94503] = { "水の呼び声", "WestfallにいるMinor Manifestation of Waterと話す。", "最後の言葉が唇を離れると同時に、光がほとばしる。水が霧へと変わるシューという音は静寂の中に消えていき、周りの堕落した精霊たちがほどけていくにつれ、あなたの感覚は揺らぐ。その本質は風に舞う灰のように散っていく。", nil, nil, 0x1f0e11aa, 0x2cab5030, 0x31813519, nil, nil, "...mm" },
  [94505] = { "水の呼び声", "Shard of WaterをLoch ModanのNorric Lochthaneに届ける。", "shardを取れ。shardを取り、命を与えよ。\n\n命を与え、理解せよ。水は命だと理解せよ……穢れは命を止める。\n\nお前は水の力で命を守り、与える。", nil, nil, 0x1f0e11aa, 0x038a8a5c, 0x1bc4c72c, nil, nil, "...mm" },
  [94559] = { "未使用", "Shen'dar HighlandsでAl'Aketh Turncoatを探し出して下さい。", "Al'Akethの中に裏切り者がいる。奴は教団がこの島で何を企んでいるのか本当のところを知っていると言い、こちらに寝返りたがっているが、身の安全が保証されなければ応じないそうだ。\n\nその離反者はValanaarのすぐ北西、高地に入ってすぐの家に隠れている。誰にも気づかれずにそこへ行き、裏切り者を見つけ出し、話を聞いて我々のもとへ連れ帰れる者が必要だ。罠かもしれないが、この情報が本人の言うとおり重要なら、多少の危険を冒す価値はある。", nil, nil, 0xe7944cd2, 0x1c0f7bd4, 0x820b6736, nil, nil, "...mm" },
  [94568] = { "教団の真の計画", "Talaanis Shadowsongと話し、会話を見守ってください。", "あの裏切り者は、教団の企みを明らかに恐れていた。我々のもとへ寝返り、助けを求めるほどにな。奴が死んで、秘密を墓場まで持っていってしまったのは本当に残念だ。\n\n次の手を決めるため、この件をもっと話し合わねばならん。", nil, "治安維持の兵を送ってカルトの勢力と直接戦わせることもできるが、正面からの戦いでは彼らにかなわないだろう。\n\n別のやり方が必要になる。", 0xb5a1a1cb, 0x8a14b2e2, 0x0db307b1, nil, 0xe24a2261, "...m." },
  [94616] = { "Water Sapta", nil, nil, nil, nil, 0xcd2fb34a, nil, nil, nil, nil, ".mmmm" },
  [94638] = { "力と慈悲", "Shen'dar HighlandsでUr'endraを見つけて倒してください。", "そなたは力の姿をとるすべを学びたいと願って、我のもとへ来たのだな。そなたに課す務めがある。我が心には重くのしかかるものだが。\n\n我が伴侶Ur'endraは狂気に呑まれ、己の同胞を襲い始めた。風の魔法を失い、多くの生き物が己を見失い始めている……Ur'endraもその一つだ。彼女はここから西の洞窟を棲み処にしている。Shen'dar HighlandsとGustberry Lowlandsの境にある断崖の中だ。\n\n彼女の苦しみを終わらせてやれば、我が祝福を授けよう。", nil, nil, 0x063a7e36, 0xbdfde440, 0x62e9d1a9, nil, nil, "...mm" },
  [94773] = { "神の恩寵", nil, nil, nil, nil, 0x4199a5e1, nil, nil, nil, nil, ".mmmm" },
  [94774] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "あなたは上の方々の目に留まったのですよ、{name}。できるだけ早くStormwindのCathedral of Lightへ来てほしいとのことです。どうやら、あなたはすでに自分を証明したと考えていて、さらに修行を進める準備ができているようです。着いたらHigh Priestess Laurenaを探してください。彼女がさらに導いてくれるでしょう。幸運を。光があなたと共にありますように。", nil, nil, 0x4199a5e1, 0x8de762b6, 0xe9bfda0e, nil, nil, "...mm" },
  [94775] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "Eluneの祝福を、善き{race}よ。今日もあなたの光があなたを見出し、よく守ってくれますように。\n\n少し前に、あなたの側のプリーストがあなたを探してここへ来ました。できるだけ早くCathedral of Lightへ戻り、High Priestess Laurenaと話すようにとのことでした。それほどの注目を集めるとは、よく励んできたのですね。ここに長居はしない方がいいでしょう。あなたの同胞があなたを必要としています。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x93d8c9e5, nil, nil, "...mm" },
  [94776] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "Stormwindへ向かう時が来たよ、{name}。Cathedral of LightのHigh Priestess Laurenaがあんたと話したいってさ。High Priestessがじきじきに呼ぶなんて、よほどいいことか、よほど悪いことに違いないけど、あんたはうまくやってきただけだろうし、話したいってのはいいことだと思うよ。\n\nでも、このへんでぐずぐずしてちゃだめだよ。俺ならできるだけ早く向かうね。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x0e82ce63, nil, nil, "...mm" },
  [94777] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話して下さい。", "ほんの少し前、あなたの同胞のプリーストがあなたを探してここに来ていましたよ、{race}。もしあなたに会ったら、Cathedral of Lightへ向かうよう伝えてほしいとのことでした。とても大事な用だと言っていましたが、私があなたなら、あまり心配はしません。あの方の様子は明るいものでした……まるで良い知らせであるかのように。私なら、そこへ向かうのにあまり時間はかけませんね。\n\nEluneの加護がありますように、善き{race}よ。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x1cfc2115, nil, nil, "...mm" },
  [94778] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "Stormwindであなたが必要とされているぞ、{name}。そこのHigh PriestessのLaurenaが、修行の次の段階にふさわしいことを証明する時だと言っている。向かうのにあまり時間をかけるな。彼女は街の中心にあるCathedral of Lightにいる。よろしく伝えてくれ。そして、その使命にどれほどふさわしいかを証明してこい。光があなたと共にあらんことを、{name}。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x8ea469d6, nil, nil, "...mm" },
  [94779] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話して下さい。", "Eluneに、そしてあなたの光に賛美を、{name}。\n\nこの頃になると、我々の教団の多くの者はEluneへの信仰を映した能力を学びます。私の知識が確かなら、あなたの教団でも同じことが言えるはずです。\n\nDarnassusでの用事が済んだら、さらなる修練のために、あなたの教団のHigh Priestessesの一人を訪ねるとよいでしょう。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x9d972e4f, nil, nil, "...mm" },
  [94789] = { "大気の呼び声", "Arathi HighlandsでVeyric Thunderveinを見つける。", "Azerothの風がお前さんを迎えとるぞ。お前さんはもうすぐ、わしらの最も強大な同胞たちと肩を並べることになる。ここまで来たのを見られて誇らしいわい。お前さんの未来は実に明るいな。\n\n風の元素を極めるのは難しいもんだが、お前さんの腕ならどんな試練も乗り越えられると信じとる。\n\n北へ進んでArathi Highlandsへ行け。その北の丘陵でVeyric Thunderveinに会えるだろう。あいつがもっと教えてくれる。", nil, nil, 0x8f4acf86, 0xe1756af1, 0x9b177a55, nil, nil, "...mm" },
  [94792] = { "獣を手なずける", "Taming Rodを使ってRockhide Boarを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。", "多くのハンターは動物の相棒を連れて旅することを好みます。獣がそばにいれば、どれほど危険な状況でも生き延びられることがわかるでしょう。よく言うように、友がいれば何事もたやすくなるものです。けれども、動物の相棒を得るには慎重さが必要です。自然の均衡は繊細で、常に尊重されなければなりません。\n\nこのTaming Rodを持って森へ行きなさい。これを使えばRockhide Boarを手なずけ、ハンターとしての技を磨けるでしょう。", "君は学ぶだろう、{name}。そしていつの日か、偉大な{class}になるだろう。", "見事だ、{name}！ 実に覚えが早いな。", 0xecd97a9a, 0x19efabbc, 0x69a91737, 0xe5057f89, 0x7f1a8496, "....." },
  [94793] = { "獣を訓練する", "GoldshireのIsaac Chanと話してください。", "あなたはペットを手なずける力を得ましたが、それを訓練する技も身につけなければなりません。それには、生涯を森で過ごしてきたIsaac Chanに勝る者はいません。彼が新しいペットを訓練する力を授けてくれるでしょう。\n\n風と共に行きなさい、若き{class}よ。", nil, "駆け出しの{class}だな。よかろう、ペットを訓練し導くのに必要な技を授けよう。ペットに新しい能力を教えられるだけでなく、これからはペットに餌を与え、戦いで倒れたときには蘇らせることもできるようになる。\n\n忘れるな、{name}。常に均衡を重んじ、周りの自然に畏敬の念を抱いて生きるのだ。さあ、行くがよい。また後日、話そう。", 0xdbeedc0e, 0xf8c4ebf2, 0x4bc880b0, nil, 0xfbd746d0, "...m." },
  [94817] = { "惑わしの閃光", nil, nil, nil, nil, 0xd8782324, nil, nil, nil, nil, ".mmmm" },
  [94818] = { "Contingency Plan", nil, nil, nil, nil, 0x584b30b7, nil, nil, nil, nil, ".mmmm" },
  [94819] = { "Contingency Plan", "IronforgeのHigh Priestess Mimsと話す。", "{name}、あなたのHigh Priestess MimsがIronforgeであなたとの面会を望んでいます。急いでください、賢い友よ。次の試練がすぐそこまで迫っています。あなたの種族独自の儀式に立ち会えればと願うのですが、私の居場所はここです。それでも、旅路に光が共にあらんことを。街に着いたら、MimsはまだMystic Wardにいるはずです。彼女が待っています。", nil, nil, 0x584b30b7, 0x656c5f67, 0xf8b55805, nil, nil, "...mm" },
  [94820] = { "非常時の計画", "IronforgeのHigh Priestess Mimsと話して下さい。", "あなたの種族は本当に賢いですね、{name}。あなたがたを盟友と呼べることを誇りに思います。そして日が沈むたびに、あなたとあなたの同胞は故郷の街を取り戻す日に近づいていますが、亡命先で家族を守るという重荷も背負っています。故郷への思いは、さぞ重くのしかかっていることでしょう。\n\nつい最近、Ironforgeから知らせが届きました。そこへ戻り、Mystic WardのHigh Priestess Mimsと話すようにとのことです。彼女を待たせてはいけませんよ。Eluneがあなたの旅を導いてくれますように。", nil, nil, 0x584b30b7, 0x656c5f67, 0xfc0c8df4, nil, nil, "...mm" },
  [94821] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "最近、プリーストがひとり、あなたを探して私たちの広間を訪れました、若き{race}よ。あなたを見つける使命を帯びていて、できるだけ早くIronforgeのHall of Mysteriesへ戻るように、とのことでした。着いたらHigh Priestess Mimsを訪ねてください。詳しいことは彼女が教えてくれるでしょう。\n\n光があなたと共にありますように、{name}。", nil, nil, 0xd8782324, 0x656c5f67, 0xb61e2669, nil, nil, "...mm" },
  [94822] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "あなたは上の方々の目に留まったのですよ、{name}。できるだけ早くIronforgeのHall of Mysteriesへ来てほしいとのことです。どうやら、あなたはすでに自分を証明したと考えていて、さらに修行を進める準備ができているようです。着いたらHigh Priestess Mimsを探してください。彼女がさらに導いてくれるでしょう。幸運を。光があなたと共にありますように。", nil, nil, 0xd8782324, 0x656c5f67, 0x591115c6, nil, nil, "...mm" },
  [94823] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "Eluneの祝福を、善き{race}よ。今日もあなたの光があなたを見出し、よく守ってくれますように。\n\n少し前に、あなたの側のプリーストがあなたを探してここへ来ました。できるだけ早くHall of Mysteriesへ戻り、High Priestess Mimsと話すようにとのことでした。それほどの注目を集めるとは、よく励んできたのですね。ここに長居はしない方がいいでしょう。あなたの同胞があなたを必要としています。", nil, nil, 0xd8782324, 0x656c5f67, 0xf4f34293, nil, nil, "...mm" },
  [94824] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "そろそろIronforgeへ向かう時だぞ、{name}。Hall of MysteriesのHigh Priestess Mimsが、お前に来て話をするよう命じとる。大司祭がわざわざお前を呼びつけるなんて、よっぽど良いことか、よっぽど悪いことに違いない。だが、お前はうまくやってきたんだろうし、彼女が話したがっとるのは良い知らせだと思うがな。\n\nとはいえ、ここであまりぐずぐずするなよ。わしならできるだけ早く向かうぞ。", nil, nil, 0xd8782324, 0x656c5f67, 0x68f292b0, nil, nil, "...mm" },
  [94825] = { "Confounding Flash", "IronforgeのHigh Priestess Mimsと話す。", "ついさっき、あなたの教団のプリーストの一人があなたを探しにここへ来ました、{race}。もし私があなたに会ったら、Hall of Mysteriesへ行くよう伝えてほしいと。とても大切なことだと言っていましたが、私ならあまり心配はしません。彼の様子は明るく……まるで良い知らせのようでした。私があなたなら、あまり時間をかけずに向かいますね。\n\nEluneのご加護を、善き{race}よ。", nil, nil, 0xd8782324, 0x656c5f67, 0xa819c88b, nil, nil, "...mm" },
  [94826] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "Eluneに、そしてあなたの光に讃えあれ、{name}。\n\nこの頃になると、私たちの教団の多くはEluneへの信仰を映す力を学びます。私の知る限り、あなたの教団でも同じことが言えるはずです。\n\nDarnassusでの用事が済んだら、さらなる修行のためにあなたのHigh Priestessを訪ねるとよいでしょう。", nil, nil, 0xd8782324, 0x656c5f67, 0x560c66c6, nil, nil, "...mm" },
  [94863] = { "獣を手なずける", "Taming Rodを使ってGray Forest Wolfを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。", "お前はすでに猪を手なずけることを身につけた。次の教えに進む時だ。森にはもっと獰猛な仲間がいる。慎重に接すれば、その信頼を得られるだろう。\n\nこのTaming Rodを持って、Gray Forest Wolfを探し出せ。忘れるな、自然の均衡は尊重されねばならない。ハンターとしての腕前を、もう一度証明してみせろ。", "学びの先に、{name}、熟達がある。", "よくやった、{name}！ 獣とすっかり心が通じ合っているな。", 0xecd97a9a, 0x18dda32c, 0x213604b0, 0x968b687d, 0xee58c591, "....." },
  [94864] = { "獣を手なずける", "Taming Rodを使ってYoung Forest Bearを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。", "猪と狼を手なずけて、お前は自分の力を証明した。いよいよ最後の挑戦の時だ。Elwynnの均衡は、敬意と技にかかっている。このTaming Rodを持って、Young Forest Bearを探し出せ。最も力強い仲間の信頼さえ得られることを示してみせろ。\n\nこの教えをやり遂げれば、獣との絆がより深まるだろう。", "行くがいい、{name}。Elwynnで最もたくましい獣を手なずけてくるのだ。", "森の剛力だな。勇敢な働きだったぞ、{name}！", 0xecd97a9a, 0x4d82c2d9, 0x1a8183ea, 0x62dcf008, 0x40ad2d6e, "....." },
  [94872] = { "友好を買う：Magram", "Totem ToteをDesolaceのMagram VillageにいるMagram Quartermasterに届け、その氏族との評判を大きく上げる。Magram Clan Centaurとの関係が中立以上でなければならない。", "今のところ、猛々しいMagramが縄張り争いに勝っているのは間違いない。砂漠のあちこちで衝突があまり頻繁に起きていないのはありがたいが、すぐ東にある奴らの村は日に日に少しずつ大きくなり、兵士たちは少しずつ大胆になっている。\n\n抑えの効かないMagram氏族がもたらす結果を深く憂慮しているが、味方としての奴らの可能性は否定できない。\n\n奴らの信頼を得たいなら、このトーテムの袋を奴らの補給係に差し出せ。だが気をつけろ。", nil, nil, 0xf5fd14ba, 0x66df78e4, 0x4c0d5c32, nil, nil, "...mm" },
  [94873] = { "友好を買う：Gelkis", "Totem ToteをDesolaceのGelkis VillageにいるGelkis Quartermasterに届け、その氏族との評判を大きく上げる。Gelkis Clan Centaurとの関係が中立以上でなければならない。", "どちらの有力なcentaur氏族も良い味方になりそうだが、Gelkisについては一言注意しておくべきだろう。\n\n信頼できる情報によれば、MagramとGelkisのうち、後者はかなり負けている側だ。これは我々に有利に働くかもしれない。追い詰められた孤立した氏族が、外からの助けに心を開くかもしれないからだ。\n\nGelkis Villageの補給係のところへ、そもそもいればの話だが、持っていってもらうトーテムの袋を用意しておいた。これは我々に有利に働くかもしれない。", nil, nil, 0x57c3db29, 0x68c32afb, 0x03629ec5, nil, nil, "...mm" },
  [94896] = { "難民への支援", "Ban'aethalの廃墟からAbandoned Belongingsを$N1個集めてください。", "頼りになりそうな冒険者さんですね。もしかしてShadowgale Forestへ向かうところですか？ Ban'aethalはその森の奥にあります。私たちは皆そこから来たのです。\n\n<Ealaaneは他の避難民たちを指し示す。>\n\n最近、Ban'aethalが空へ落ち始めたので、私たちは避難しなければなりませんでした。真夜中に、突然のことでした。もしそちらへ向かうなら、残してきた持ち物を探していただけませんか？ 森も村も危険すぎて、今の私たちには戻れないのです。", "我々の多くは、着の身着のままで逃げ出した。取り戻してもらえる持ち物があれば、何であれ大切にされるだろう。", "ありがとうございます、{class}。今日、あなたは私たち難民にとても親切にしてくださいました。これは必ず持ち主に返します。少なくとも、やり直すための足がかりにはなります。", 0x0098f2fc, 0x0e6b1138, 0x187b86ed, 0x0ca628e1, 0xca01c297, "....." },
  [94897] = { "愛する者の運命", "Ruins of Ban'aethalでResaanを見つけてください。", "Ban'aethalへ行かれるのなら、身勝手なお願いがあります。愛するResaanは……もうこの世にはいないのだと思います。私がここにいてと懇願したのに、彼は物資を取りに戻ろうとしたんです。もう一週間以上経っていて、最悪の事態を恐れています。\n\nどうか、彼を見つけたら、家に連れて帰ってきてください。もし亡くなっていたら、お願いです、彼の家宝を私のもとへ持ってきてください。", "Resaanの知らせは何かありますか？お願いです、{class}、あんなことがあった後では、待つのがつらくてたまらないのです。", "<Ealaaneの目に涙があふれる。>\n\nああ、Resaan、愛しい人。私たちはこれからどうなるの？ たくさんのことがあったのに……二人の人生は始まったばかりのような気がするわ。\n\nありがとう、{class}。家だけでなく愛する人まで奪うなんて、世界は残酷ね。でも少なくとも、彼の形見があれば少しは気持ちに区切りがつけられるわ。", 0xb884fe2f, 0xf98283dc, 0xe9621309, 0xf8b4f756, 0x075c1bde, "....." },
  [94898] = { "激しい風（一時無効）", "Wind Hollowを$N1体倒す。", "あの運命の夜、私たちの故郷が空へと落ち始めたとき、まるで精霊たち自身が私たちを呑み込もうと待ち構えていたかのようでした。逃げる途中で風の精霊たちが現れ始め、恐ろしいことに、逃げ惑う生存者たちを襲い始めたのです。\n\n多くの村人が空に消えましたが、それ以上に多くの者が、あの風の精霊たちの容赦ない怒りの犠牲になりました。村が空へ落ちていったせいなのかは分かりませんが、彼らはとても危険です。\n\nもしできるなら、彼らを眠らせてあげてください。", nil, nil, 0xb67e7fc6, 0x131d9d41, 0x7cad8caa, nil, nil, "...mm" },
  [94901] = { "跳ねる助っ人たち", "Gustjumperの蛙を$N1匹集める。", "[PH] カエルを集める", nil, nil, 0x948903fd, 0x0d6a2d17, 0xa1d51fdc, nil, nil, "...mm" },
  [94902] = { "Valanaarの銘酒", "$N1個のブドウを集める。", "[PH] ブドウ園でブドウを集める", nil, nil, 0xeeccf2b3, 0xf13640b3, 0x7ee77c4a, nil, nil, "...mm" },
  [94911] = { "自然の子", "Thunder BluffのTurak Runetotemと話してください。", "ごきげんよう、若き{race}よ。あなたにはドルイドの術の大きな素質が見えます。Thunder Bluffの街に、Turak Runetotemという名の、話をしておくとよい方がいます。彼が、KalimdorにあるCenarion Circleの拠点、Moongladeへ行く方法を教えてくれるでしょう。\n\nあなたはそこで歓迎され、Circleのドルイドたちがその知識をあなたに授けてくれるでしょう。\n\nあなたの同胞の言い方を借りれば……風の祝福と共に行きなさい、若き者よ。あなたの冒険に幸運がありますように。", nil, "ハイエルフが私に話しかけてくるとは……それもThunder Bluffで。驚きは尽きないものだな。\n\nさて、風を形作る者よ、Earthen Ringの兄弟姉妹たちと共に、そなたをAzerothへ歓迎させてもらおう。Cenarion Circleの同志のドルイドたちが、自然の子であるそなたに多くの知恵を授けるだろう。", 0xb806d7b4, 0x724e1ed0, 0x87d83a15, nil, 0x22a61e0c, "...m." },
  [94912] = { "自然の子", "StormwindのSheldras Moontreeと話してください。", "ごきげんよう、若き{class}よ。\n\nCenarion Circleについて聞いたことはありますか？ おそらくないでしょうね。彼らは自然を探究し、ドルイドの術を修める古い結社で、あなたとよく似た者たちです。Stormwindの街に、Sheldras Moontreeという名のナイトエルフがいます。彼が、KalimdorにあるCenarion Circleの拠点、Moongladeという場所へ行く方法を教えてくれるでしょう。\n\nさあ、行きなさい。故郷を救いたいのなら、学ぶべきことはたくさんあります。", nil, nil, 0xb806d7b4, 0x59f95b86, 0xfd0dcca7, nil, nil, "...mm" },
  [94913] = { "Moonglade", "呪文「Teleport: Moonglade」を使ってMoongladeへ移動してください。到着したら、Nighthavenの村にいるDendrite Starblazeと話してください。", "すべてのドルイドは、Moongladeの聖なる地に迎え入れられる。Moongladeの守護者であるKeeper Remulosは、そこで冬眠するすべてのドルイドを見守っている。そこへ自らを運ぶ呪文を教えよう。Moongladeの知恵や安らぎを求めるときは、いつでも唱えるがいい。\n\nここAzerothでの最初の教えとして、Moongladeへ旅し、NighthavenのDendrite Starblazeに、お前が今歩んでいる道について話を聞くのだ。幸運を祈る、若きドルイドよ。", nil, "ほう、もうBearの姿を会得したようだな。よし、よし。順調に進んでいるぞ、若き{class}。", 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, 0x0e12a96b, "...m." },
  [94914] = { "Moonglade", "呪文「Teleport: Moonglade」を使ってMoongladeへ移動してください。到着したら、Nighthavenの村にいるDendrite Starblazeと話してください。", "すべてのドルイドは、Moongladeの聖なる地に迎え入れられる。Moongladeの守護者であるKeeper Remulosは、そこで冬眠するすべてのドルイドを見守っている。そこへ自らを運ぶ呪文を教えよう。Moongladeの知恵や安らぎを求めるときは、いつでも唱えるがいい。\n\nここAzerothでの最初の教えとして、Moongladeへ旅し、NighthavenのDendrite Starblazeに、お前が今歩んでいる道について話を聞くのだ。幸運を祈る、若きドルイドよ。", nil, nil, 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, nil, "...mm" },
  [94946] = { "魔法都市Dalaran", "Zephras Isleからスカイカッター船に乗ってDalaran Cityへ向かい、到着したらDanaaris Stargaleと話してください。", "我々の中で最初にAzerothの地を踏むのは私のつもりだったが、カルトをめぐる最近の出来事で予定が変わった。そのため、しばらくはここValanaarに残ることになる。だが心配はいらない。Dalaranでは何人ものメイジが我らの民の到着を待っている。我々がここで態勢を整える間、君にはAzerothを探索してほしい。必要な時には、君のような者たちに声をかける。\n\n準備ができたら、このロッジのすぐ外の桟橋へ行き、そこのskycutter船に乗ってくれ。", nil, "ああ、着いたか。何よりだ。ここで落ち着くまでにはしばらく時間がかかるから、その間に街を見て回るといい。ただし気をつけてくれ。安全な街の中心からあまり遠くへは行かないように。\n\nこの新しい土地はのどかに見えるが、十分な準備と経験もなしにDalaranの外をうろつくのは非常に危険だ。", 0x26c38851, 0x00903656, 0xb66f8dd9, nil, 0x711ff0fc, "...m." },
  [94947] = { "Azerothへようこそ", "Skyborne Portalを使ってStormwindへ行き、Stormwind KeepのBolvar Fordragonに報告してください。", "この下の世界は広い。我々の民も枝分かれして、それを探検し始める必要がある。そこで君の出番だ。\n\nKirin Torは、志を同じくする国々の「Alliance」の一員だ。この同盟の事実上の中心は、南にあるStormwindの街だ。Elaadrinから、Stormwindへ旅してそこの摂政に会う者を探すよう頼まれている。Bolvar Fordragonという名の人間だ。\n\n準備ができたら、High OrderがStormwindへ行けるよう、Kirin Torのメイジたちが特別なポータルを用意してくれている。", nil, "よく来た、{class}。私はBolvar Fordragon、Stormwindの王座の摂政だ。\n\nKirin Torの使者から、High Orderの者たちを迎えることになると聞いていたが、こうしてそなたが立っている。ハイエルフがこの玉座の間に立つのは久しぶりだが、今こうして客人として迎えられることを嬉しく思う。\n\n王に代わり、Stormwindへの来訪を歓迎し、Allianceの領地を自由に旅することを許可する。Azerothへようこそ、{race}。", 0x2f003d6f, 0x9e17660a, 0xc4f3c12d, nil, 0x6e9dee83, "...m." },
  [94978] = { "獣を手なずける", "Taming Rodを使って水辺にいるWindsong Crawlerを手なずけてください。\n技を練習したら、Taming RodをValanaarのQuel'ana Quickgaleに返してください。", "どのハンターも、獣と主人の絆を学ぶことから始めます。これがあなたの最初の試練です。いずれあなたは世界の隅々の生き物を手なずけることになるでしょうが、今はここZephrasの川や湖から始めましょう。\n\nこのTaming Rodを持って、Windsong Crawlerを探しなさい。\n\nその信頼を得られることを示し、真の熟達への道を歩み始めてください。", "君は学ぶだろう、{name}。そしていつの日か、偉大な{class}になるだろう。", "見事に手なずけたな、{name}！ もう腕を上げつつある。", 0xecd97a9a, 0xc2ec4aaf, 0x97c66def, 0xe5057f89, 0x23710c4e, "....." },
  [94979] = { "獣を手なずける", "Taming Rodを使ってGustberry LowlandsのOrnery Galestriderを手なずけてください。\n技を練習したら、Taming RodをValanaarのQuel'ana Quickgaleに返してください。", "お前は川の這う者を手なずけられることを証明した。次は開けた土地で腕を試す時だ。Zephrasの平原には、風のように駆ける誇り高き翼のハンター、galestriderの鳴き声が響いている。\n\nこのTaming Rodを持って、一頭探し出せ。低地へ旅し、その信頼を勝ち取るのだ。\n\nこの先に待つ試練への準備ができていることを示してみせろ。", "君は学ぶだろう、{name}。そしていつの日か、偉大な{class}になるだろう。", "もう戻ったのか！ 大した速さだな、{name}！", 0xecd97a9a, 0x116b4c2f, 0x1cb8bfe1, 0xe5057f89, 0x599c5b8f, "....." },
})
